import { readdirSync, writeFileSync } from 'node:fs';

const rulesDir = new URL('../../rules/', import.meta.url);
const langs = readdirSync(rulesDir)
  .filter((file) => file.endsWith('.json'))
  .map((file) => file.slice(0, -'.json'.length))
  .sort();

const lines = [
  '// Generated by js/scripts/gen-rules.mjs from rules/*.json. Do not edit.',
  ...langs.map((lang) => `import ${lang} from '../../rules/${lang}.json' with { type: 'json' };`),
  '',
  `export const ruleFiles: Record<string, unknown> = { ${langs.join(', ')} };`,
  '',
];

writeFileSync(new URL('../src/rules.ts', import.meta.url), lines.join('\n'));
